<?php
$adminPage='customers';$adminTitle='Customers & KYC';$adminPermission='customers.view';require __DIR__.'/../includes/admin_header.php';$q=trim($_GET['q']??'');$kyc=$_GET['kyc']??'';$params=[];$where=["u.role='customer'"];if($q!==''){$where[]='(u.full_name LIKE ? OR u.email LIKE ? OR a.account_number LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term);}if($kyc!==''){$where[]='u.kyc_status=?';$params[]=$kyc;}$stmt=$pdo->prepare('SELECT u.user_id,u.full_name,u.email,u.phone,u.status,u.kyc_status,u.is_active,u.created_at,a.account_number,a.balance_cents FROM users u LEFT JOIN accounts a ON a.user_id=u.user_id WHERE '.implode(' AND ',$where).' ORDER BY u.created_at DESC LIMIT 100');$stmt->execute($params);$customers=$stmt->fetchAll();
?>
<form class="toolbar" method="get"><div class="field"><label for="q">Search customer</label><input id="q" name="q" value="<?=e($q)?>" placeholder="Name, email, account"></div><div class="field"><label for="kyc">KYC status</label><select id="kyc" name="kyc"><option value="">All states</option><?php foreach(['not_started','pending','under_review','verified','rejected','needs_information','expired'] as $state):?><option value="<?=e($state)?>" <?=$kyc===$state?'selected':''?>><?=e(str_replace('_',' ',$state))?></option><?php endforeach?></select></div><button class="button button-primary">Filter</button></form><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Account</th><th>Balance</th><th>KYC</th><th>Access</th><th></th></tr></thead><tbody><?php foreach($customers as $row):?><tr><td><strong><?=e($row['full_name'])?></strong><br><small><?=e($row['email'])?></small></td><td class="mono"><?=e($row['account_number']??'—')?></td><td class="money"><?=Money::format((int)($row['balance_cents']??0))?></td><td><span class="badge <?=e($row['kyc_status'])?>"><?=e(str_replace('_',' ',$row['kyc_status']))?></span></td><td><?=$row['is_active']?'Active':'Restricted'?></td><td><a class="button button-secondary" href="customer.php?id=<?=$row['user_id']?>">Review</a></td></tr><?php endforeach?></tbody></table></div><?php if(!$customers):?><div class="empty">No customers match these filters.</div><?php endif?></section><?php require __DIR__.'/../includes/admin_footer.php';?>
